async function e(){const t=await fetch("/api/automation");if(!t.ok)throw new Error(`Failed to fetch automations: ${t.status}`);return(await t.json()).items??[]}async function s(){const t=await fetch("/api/automation/blueprints");if(!t.ok)throw new Error(`Failed to fetch automation blueprints: ${t.status}`);return(await t.json()).blueprints??[]}async function r(t,n){const a=await fetch("/api/automation/blueprints/instantiate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({blueprint:t,values:n})});if(!a.ok){const o=await a.text();throw new Error(o.trim()||`Failed to create automation: ${a.status}`)}return(await a.json()).item}export{s as a,e as g,r as i};
